import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec3, mix, smoothstep } from 'three/tsl';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry } = ctx.THREE;
  const root = new Group();
  const resources = [];
  const timelines = [];
  let disposed = false;

  const backdropGeometry = new PlaneGeometry(7, 6);
  const backdropMaterial = new MeshBasicNodeMaterial();
  backdropMaterial.colorNode = mix(
    vec3(0.043, 0.043, 0.063),
    vec3(0.086, 0.086, 0.114),
    smoothstep(0.08, 0.94, uv().y)
  );

  const backdrop = new Mesh(backdropGeometry, backdropMaterial);
  backdrop.position.set(0, 0, -2.5);
  backdrop.renderOrder = -10;
  root.add(backdrop);

  const panelGeometry = new PlaneGeometry(2.8, 1.75);
  const panelMaterial = new MeshBasicNodeMaterial();
  panelMaterial.color.set('#16161d');

  const panel = new Mesh(panelGeometry, panelMaterial);
  panel.position.set(0, 0, 0);
  panel.renderOrder = 1;
  root.add(panel);

  const accentGeometry = new PlaneGeometry(0.1, 1.16);
  const accentMaterial = new MeshBasicNodeMaterial();
  accentMaterial.color.set('#ff2a38');

  const accent = new Mesh(accentGeometry, accentMaterial);
  accent.position.set(-1.16, 0, 0.035);
  accent.renderOrder = 2;
  root.add(accent);

  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const textObjects = [];

  for (const item of items) {
    const text = ctx.fontAtlas.createText(item.text, {
      fontSize: item.typography?.fontSize ?? 39,
      color: '#e8ecf2',
      align: 'left'
    });

    text.position.set(-0.92, -0.08, 0.065);
    text.renderOrder = 3;
    root.add(text);
    textObjects.push(text);
  }

  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((texture) => {
      if (disposed) {
        texture.dispose?.();
        return;
      }

      texture.offset.set(0, 0);
      texture.repeat.set(1, 1);
      texture.needsUpdate = true;

      panelMaterial.map = texture;
      panelMaterial.needsUpdate = true;
      resources.push(texture);
    });
  }

  root.onBeforeRender = (_renderer, _scene, camera) => {
    panel.quaternion.copy(camera.quaternion);
    accent.quaternion.copy(camera.quaternion);

    for (const text of textObjects) {
      text.quaternion.copy(camera.quaternion);
    }
  };

  root.userData.handlers = {};
  root.userData.cleanup = () => {
    if (disposed) return;
    disposed = true;

    for (const timeline of timelines) {
      timeline?.kill?.();
    }

    for (const resource of resources) {
      resource?.dispose?.();
    }

    backdropGeometry.dispose();
    panelGeometry.dispose();
    accentGeometry.dispose();

    backdropMaterial.dispose();
    panelMaterial.dispose();
    accentMaterial.dispose();

    root.onBeforeRender = null;
  };

  return root;
}
